+static void update_throttle_type(struct task_struct *task, int cpu, bool next)
+{
+	if (!cgroup_subsys_on_dfl(cpuacct_cgrp_subsys)) {
+		struct cgroup *cpuacct_cgrp;
+		struct psi_group_cpu *groupc;
+		struct task_group *tsk_grp;
+
+		rcu_read_lock();
